import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def get_packages(data):
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for p in fw.get('topLevelPackages', []):
                key = (p['id'], fw['framework'])
                pkgs[key] = p['resolvedVersion']
        result[pname] = pkgs
    return result

bp = get_packages(b)
ap = get_packages(a)

print('=== CHANGES ===')
changes = False
for proj in sorted(set(list(bp.keys()) + list(ap.keys()))):
    bpkgs = bp.get(proj, {})
    apkgs = ap.get(proj, {})
    for key in sorted(set(list(bpkgs.keys()) + list(apkgs.keys()))):
        bv = bpkgs.get(key)
        av = apkgs.get(key)
        if bv != av:
            changes = True
            print(f'{proj} | {key[0]} ({key[1]}): {bv} -> {av}')

if not changes:
    print('No changes detected')

print()
print('=== SUMMARY ===')
for proj in sorted(bp.keys()):
    print(f'{proj}: {len(bp[proj])} packages')
"

